n = ""

count = 0

mul = 1

def multi(i, j):
    mul = 1
    for k in range(i,j+1):
        if(n[k] == 0):
            i = k + 1
            j = i + 22
            return multi(i,j)
        else:
            mul = mul * int(n[k])

    return mul

i = 0
j = 22

largest_multiplication = multi(0,j)

mul = largest_multiplication

while (j<1000):
    i = i + 1
    j = j + 1

    if(n[j] == 0):
        i = j + 1
        j = i + 22
        temp_mul = multi(i,j)

    else: 
        temp_mul = (mul/int(n[i-1]))*(int(n[j]))
    

    if(temp_mul>largest_multiplication):
        largest_multiplication = temp_mul
    
    mul = temp_mul


